UNION ALL SELECT id, 'D', 'misconception', $a9D$Assumes shared anatomical location (the skin/integument) implies a shared germ-layer origin$a9D$ FROM q;

-- Q10 [Ectoderm Derivatives | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub10$Ectoderm Derivatives$sub10$, $qt10$A teratogen selectively destroys the mesoderm-derived vascular connective tissue that forms the choroid of the developing eye while leaving the neural tube and its anterior outgrowths intact. An embryologist tracks the consequences and predicts which eye structure is malformed and which is spared.$qt10$, $op10$[{"label": "A", "text": "Both the choroid and the retina are malformed, because both arise from the mesoderm-derived connective tissue of the developing eye."}, {"label": "B", "text": "The choroid is malformed but the retina is spared, because the choroid is mesoderm-derived connective tissue whereas the retina arises from the diencephalic eye cup."}, {"label": "C", "text": "The retina is malformed but the choroid is spared, because the retina is the mesoderm-derived connective tissue while the choroid arises from the diencephalic eye cup."}, {"label": "D", "text": "The choroid is malformed but the retina is spared, because the choroid forms from the endoderm-derived epithelial lining whereas the retina arises from the diencephalic eye cup."}]$op10$::jsonb, 'B', $ex10$This is a Biology question that falls under the content category 'Gastrulation & Germ Layers'. The answer is B because the choroid is mesoderm-derived vascular connective tissue and is therefore destroyed by a teratogen targeting mesodermal connective tissue, whereas the retina develops from the eye cup of the embryonic diencephalon (a neural-tube CNS derivative) and is left intact. The Anatomy and Physiology text states that the choroid is 'a layer of highly vascularized connective tissue that provides a blood supply to the eyeball,' and that mesodermal cells 'ultimately become the skeleton, muscles, connective tissue, heart, blood vessels, and kidneys,' so the choroid traces to mesoderm. The same text states that 'in the embryonic diencephalon, a structure known as the eye cup develops, which will eventually become the retina... This is a rare example of nervous tissue developing as part of the CNS structures in the embryo,' and that the diencephalon arises from the anterior neural tube; because the neural tube is left intact, the diencephalon-derived retina is spared. (Choice A) is incorrect because, although the choroid is mesoderm-derived connective tissue, the retina is neural-ectodermal tissue from the diencephalic eye cup, not a mesodermal connective-tissue derivative, so it is not destroyed. (Choice B) is correct because it assigns the choroid to mesoderm-derived connective tissue and the retina to the diencephalic eye cup of the neural tube. (Choice C) is incorrect because it reverses the origins—the retina is the neural CNS tissue from the eye cup, while the choroid, not the retina, is the mesoderm-derived connective tissue. (Choice D) is incorrect because the choroid is mesoderm-derived connective tissue, not an endoderm-derived epithelial lining; endoderm forms the epithelial lining of the gastrointestinal tract, liver, pancreas, and lungs. This is a Scientific Reasoning and Problem Solving question because it requires predicting the differential outcome of a tissue-specific insult by tracing each eye structure back to its distinct germ-layer (mesoderm versus neural-ectoderm) origin.$ex10$, 'hard', '2C', $cc10$Gastrulation & Germ Layers$cc10$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a10A$Overgeneralizes the mesodermal connective-tissue origin of the choroid to the entire eye, failing to recognize that the retina is neural ectoderm from the diencephalic eye cup rather than a mesodermal connective-tissue derivative.$a10A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a10C$Correctly identifies mesoderm-derived connective tissue versus neural eye-cup origins but swaps which structure gets which, assigning the mesodermal connective-tissue origin to the retina instead of the choroid.$a10C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a10D$Imports the true fact that endoderm forms epithelial linings and misapplies it to the choroid, which is actually mesoderm-derived vascular connective tissue, not an endodermal epithelial lining.$a10D$ FROM q;

-- Q11 [Mesoderm Derivatives | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub11$Mesoderm Derivatives$sub11$, $qt11$A histologist examines four adult tissues recovered from a single individual and traces each one back to the primary germ layer from which it arose during embryonic development. One of these tissues is correctly assigned a mesodermal origin. Which structure is it?$qt11$, $op11$[{"label": "A", "text": "The epidermis of the skin"}, {"label": "B", "text": "The epithelial lining of the gastrointestinal tract"}, {"label": "C", "text": "The skeleton (bone and cartilage)"}, {"label": "D", "text": "The brain and spinal cord"}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Gastrulation & Germ Layers'. The answer is C because the skeleton is one of the structures that develops from the mesoderm, the middle of the three primary germ layers. After gastrulation establishes the ectoderm, mesoderm, and endoderm, mesodermal cells differentiate into the skeleton, muscles, connective tissue, heart, blood vessels, and kidneys (A&P: "Mesodermal cells ultimately become the skeleton, muscles, connective tissue, heart, blood vessels, and kidneys"). By contrast, the ectoderm produces the nervous systems, sensory organs, epidermis, hair, and nails, while the endoderm produces the epithelial lining of the gut, liver, pancreas, and lungs, so only the skeleton among the listed tissues is mesodermal. (Choice A) The epidermis of the skin is incorrect because the epidermis is an ectodermal derivative, not mesodermal ("the ectoderm gives rise to cell lineages that differentiate to become the central and peripheral nervous systems, sensory organs, epidermis, hair, and nails"). (Choice B) The epithelial lining of the gastrointestinal tract is incorrect because the gut epithelium is an endodermal derivative ("The endoderm goes on to form the epithelial lining of the gastrointestinal tract, liver, and pancreas"). (Choice C) The skeleton is correct because bone and cartilage arise from mesodermal cells. (Choice D) The brain and spinal cord are incorrect because the central nervous system arises from the ectoderm ("the ectoderm gives rise to cell lineages that differentiate to become the central and peripheral nervous systems"). This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established assignment of an adult organ to its primary germ layer of origin.$ex11$, 'easy', '2C', $cc11$Gastrulation & Germ Layers$cc11$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a11A$Assigning an ectodermal derivative (epidermis) to the mesoderm by confusing the deep dermal connective tissue with the superficial epidermal layer$a11A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a11B$Naming a true germ-layer derivative but from the wrong layer (endodermal gut epithelium instead of mesoderm)$a11B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a11D$Assigning the neuroectoderm-derived CNS to the mesoderm because of the skeleton/spinal cord anatomical association$a11D$ FROM q;

-- Q12 [Mesoderm Derivatives | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub12$Mesoderm Derivatives$sub12$, $qt12$A clinician evaluates a patient whose adrenal glands have been selectively damaged so that the steroid-hormone-producing outer region no longer functions, while the catecholamine-releasing inner region remains intact. Which region of the gland is derived from the mesoderm?$qt12$, $op12$[{"label": "A", "text": "The adrenal medulla, the catecholamine-releasing inner region"}, {"label": "B", "text": "Both the cortex and the medulla, as a single mesodermal unit"}, {"label": "C", "text": "Neither region, because the entire gland is endodermal"}, {"label": "D", "text": "The adrenal cortex, the steroid-producing outer region"}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Gastrulation & Germ Layers'. The answer is D because the adrenal cortex (the steroid-producing outer region) arises from the mesoderm, whereas the medulla arises from ectodermal neural cells. The text states that "the two structures of the adrenal glands arise from two different germ layers: the adrenal cortex from the mesoderm and the adrenal medulla from ectoderm neural cells," so the damaged outer steroid-producing region described in the scenario is precisely the mesodermal cortex. Because the gland is built from two regions of two distinct germ-layer origins, assigning the mesodermal label requires discriminating the cortex from the ectoderm-derived medulla rather than treating the gland as a single unit. (Choice A) The adrenal medulla is incorrect because the medulla "from ectoderm neural cells" is the ectodermal region, the reverse of the cortex's mesodermal origin. (Choice B) Both regions equally is incorrect because the text specifies the two structures "arise from two different germ layers," so only the cortex is mesodermal. (Choice C) Neither region/entirely endodermal is incorrect because the endoderm gives rise to the thyroid, parathyroid, pancreas, and thymus, not the adrenal gland. (Choice D) The adrenal cortex is correct because the text directly states the "adrenal cortex from the mesoderm." This is a Scientific Reasoning and Problem Solving question because it requires mapping a described functional region of an organ with dual germ-layer origin onto its correct embryonic source.$ex12$, 'medium', '2C', $cc12$Gastrulation & Germ Layers$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a12A$Swapping the two germ-layer assignments within a dual-origin organ (medulla labeled mesodermal instead of cortex)$a12A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a12B$Treating a mixed-origin organ as a single uniform germ-layer derivative$a12B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a12C$Assigning the whole gland to the wrong germ layer (endoderm) by confusing it with endodermal endocrine glands$a12C$ FROM q;

-- Q13 [Mesoderm Derivatives | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub13$Mesoderm Derivatives$sub13$, $qt13$A histologist examines a cross-section of the developing intestinal tube and labels two concentric layers of the wall: a band of smooth muscle and the loose connective tissue that surrounds and supports it. The histologist is asked to trace these two labeled layers back to the germ layer from which they arose. Which structure(s) of the gut wall should be assigned to the mesoderm?$qt13$, $op13$[{"label": "A", "text": "The smooth muscle and connective-tissue layers of the gut wall"}, {"label": "B", "text": "The epithelial mucosa lining the gut lumen"}, {"label": "C", "text": "The entire gut tube including its lining"}, {"label": "D", "text": "The enteric neurons embedded in the gut wall"}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Gastrulation & Germ Layers'. The answer is A because the mesoderm gives rise to most of the muscle and connective tissues of the body, so the smooth muscle band and the surrounding connective tissue of the gut wall trace to that middle layer, while the inner mucosal lining does not. The text states that "The mesoderm, or middle tissue, gives rise to most of the muscle and connective tissues" (A&P 23156), which directly assigns both labeled layers to the mesoderm. The endoderm, by contrast, is "responsible for generating the lining tissues... such as the mucosae of the digestive and respiratory systems" (A&P 23154-23155), so the epithelial mucosa is a separate, endodermal contribution to the same tube. Because the digestive tube is built from more than one germ layer, only the muscular and connective components belong to the mesoderm. (Choice A) Correct: the smooth muscle and connective tissue are precisely the muscle and connective tissues the mesoderm forms. (Choice B) Incorrect: the epithelial mucosa lining the lumen is endodermal, not mesodermal, since the endoderm generates the mucosae of the digestive system. (Choice C) Incorrect: the muscular and connective layers are mesodermal, but the lining is endodermal, so the entire tube cannot be assigned to the mesoderm. (Choice D) Incorrect: enteric neurons are nervous tissue, which "derives primarily from the ectoderm," not the mesoderm. This is a Scientific Reasoning and Problem Solving question because it requires applying the rule that the gut is a mixed-origin structure to a specific scenario, discriminating which labeled wall layers map to mesoderm versus the endodermal lining.$ex13$, 'medium', '2C', $cc13$Gastrulation & Germ Layers$cc13$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a13B$Attributing a co-located, real germ-layer derivative (the endodermal mucosal lining) to the wrong layer$a13B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a13C$Correct for the muscular/connective layers but over-extends mesodermal origin to the whole tube, including the endodermal lining$a13C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a13D$Naming a real gut-wall component (enteric neurons) whose true origin is ectoderm, not mesoderm$a13D$ FROM q;

-- Q14 [Mesoderm Derivatives | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub14$Mesoderm Derivatives$sub14$, $qt14$A histologist examines a cross-section of a muscular artery and traces every cellular layer back to its embryonic germ layer of origin: the inner endothelial lining of the lumen, the smooth muscle of the tunica media, and the connective tissue of the vessel wall. The histologist asks a student to assign each of these three components to its correct germ layer.$qt14$, $op14$[{"label": "A", "text": "The endothelial lining is endodermal, whereas the smooth muscle and connective tissue of the wall are mesodermal."}, {"label": "B", "text": "The endothelial lining, the smooth muscle, and the connective tissue of the wall are all mesodermal."}, {"label": "C", "text": "The endothelial lining is ectodermal, whereas the smooth muscle and connective tissue of the wall are mesodermal."}, {"label": "D", "text": "The endothelial lining, the smooth muscle, and the connective tissue of the wall are all endodermal."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Gastrulation & Germ Layers'. The answer is B because every component of a blood vessel — the inner endothelial lining as well as the surrounding smooth muscle and connective tissue — traces back to the embryonic mesoderm. During early development, "blood vessels begin to form from the embryonic mesoderm. The precursor cells are known as hemangioblasts... differentiate into angioblasts, which give rise to the blood vessels," and the endothelial lining arises from these mesoderm-derived angioblasts while "surrounding mesenchymal cells give rise to the smooth muscle and connective tissue layers." The endothelial lining is a tempting trap because its name evokes "endoderm," but the text is explicit that "the epithelium that lines vessels in the lymphatic and cardiovascular system derives from the mesoderm and is called an endothelium." The endoderm gives rise to the lining of the airways and digestive tract, not to the lining of hollow organs that do not connect to the exterior such as blood vessels, which are instead lined by mesoderm-derived endothelium. (Choice A) is incorrect because it assigns the endothelium to the endoderm, but the text states the vessel endothelium "derives from the mesoderm"; the endoderm lines the digestive and respiratory tracts, not vessels. (Choice B) is correct because the endothelium arises from mesodermal angioblasts and the wall's smooth muscle and connective tissue arise from surrounding mesenchyme, so all three are mesodermal. (Choice C) is incorrect because the ectoderm gives rise to surface epithelia such as the skin and the lining of the mouth and anus, not the endothelium, which is mesodermal. (Choice D) is incorrect because, although blood vessels are hollow internal tubes, those that do not open to the exterior are lined by mesoderm-derived endothelium rather than by endoderm, which lines the gut. This is a Scientific Reasoning and Problem Solving question because the student must reconcile the misleading "endo-" terminology with the textbook's explicit germ-layer assignments and chain the endothelium-versus-wall distinction to the single conclusion that the entire vessel is mesodermal.$ex14$, 'hard', '2C', $cc14$Gastrulation & Germ Layers$cc14$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a14A$Name-based confusion: the 'endo-' in endothelium lures the student to assign the lining to endoderm while correctly keeping the wall mesodermal (510-tempting single-variable split).$a14A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a14C$Wrong-layer epithelium: assigns the lining to ectoderm by confusing endothelium with an outer/surface ectodermal epithelium (e.g., skin/mouth lining).$a14C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a14D$Hollow-tube-equals-gut reasoning: treats vessels like the endoderm-lined digestive tube, ignoring that internal organs not opening to the exterior are lined by mesodermal endothelium.$a14D$ FROM q;

-- Q15 [Mesoderm Derivatives | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub15$Mesoderm Derivatives$sub15$, $qt15$During the fourth week of human development, a researcher labels the cells of a single paraxial somite flanking the neural tube and tracks the labeled lineage into the mature trunk. One labeled structure later contracts to flex the vertebral column. Which mature structure derived from that somite is the labeled contractile tissue the scenario describes?$qt15$, $op15$[{"label": "A", "text": "The motor neurons that innervate the muscle, because they descend from the same somite that lies adjacent to the neural tube"}, {"label": "B", "text": "The notochord the somite flanks, because it is the rod-shaped mesoderm-derived axis running through the trunk"}, {"label": "C", "text": "The skeletal muscle fibers, because trunk skeletal muscle develops from the mesodermal somite that forms alongside the neural tube"}, {"label": "D", "text": "The overlying epidermis covering the muscle, because surface tissue arises from the same paraxial somitic blocks"}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Gastrulation & Germ Layers'. The answer is C because trunk skeletal muscle is a mesodermal derivative that forms specifically from the paraxial somites lying beside the neural tube, and only the muscle fibers are both somite-derived and contractile. The A&P text states that "Most muscle tissue of the body arises from embryonic mesoderm. Paraxial mesodermal cells adjacent to the neural tube form blocks of cells called somites. Skeletal muscles, excluding those of the head and limbs, develop from mesodermal somites," and that somites differentiate into "the axial skeleton, skeletal muscle, and dermis." The somite lies next to the neural tube but is a distinct mesodermal block, so structures that are merely adjacent (the ectodermal neural tube) or that share the mesoderm germ layer (the notochord) are not the contractile somite product the scenario tracks. (Choice A) is wrong because the neural tube and the motor neurons that arise from it are ectodermal/neuroectodermal derivatives — the text describes "a portion of the ectoderm" differentiating into "neuroectoderm... the precursor for the tissue of the nervous system" — so the nerve, despite lying next to the somite, is not somite-derived. (Choice B) is a tempting trap because the notochord is genuinely mesoderm-derived ("the tube lies atop a rod-shaped, mesoderm-derived notochord"), but it is the axis the somites flank, not the somite-derived contractile muscle the scenario asks about. (Choice C) is correct because the labeled, somite-derived, vertebrae-flexing contractile tissue is skeletal muscle, which the text assigns to the mesodermal somite. (Choice D) is wrong because the epidermis is an ectodermal derivative — "The ectoderm gives rise to cell lineages that differentiate to become the central and peripheral nervous systems, sensory organs, epidermis, hair, and nails" — not a product of the mesodermal somite. This is a Scientific Reasoning and Problem Solving question because it requires tracing a labeled lineage and discriminating the true mesodermal-somite contractile product from adjacent ectodermal structures and from a same-germ-layer but non-muscle mesodermal derivative.$ex15$, 'hard', '2C', $cc15$Gastrulation & Germ Layers$cc15$, 'biology', 2, 150
  ) RETURNING id
)
